// Dashboard Component
const Dashboard = ({ user, kycStatus, accountStatus }) => {
  const [activeTab, setActiveTab] = useState("transfer");
  const [walletId, setWalletId] = useState("");
  const [receiverWalletId, setReceiverWalletId] = useState("");
  const [amount, setAmount] = useState("");
  const [totalCoins, setTotalCoins] = useState(1000); // Total ETH balance
  const [notification, setNotification] = useState("");
  const [transactionHistory, setTransactionHistory] = useState([]);
  const [conversionType, setConversionType] = useState("coinToUsd");
  const [conversionAmount, setConversionAmount] = useState("");
  const [conversionResult, setConversionResult] = useState("");
  const [depositAmount, setDepositAmount] = useState("");
  const [depositBankAccount, setDepositBankAccount] = useState("");
  const [withdrawAmount, setWithdrawAmount] = useState("");
  const [withdrawBankAccount, setWithdrawBankAccount] = useState("");
  const [is2FAEnabled, setIs2FAEnabled] = useState(false); // 2FA state
  const [showSettings, setShowSettings] = useState(false); // Settings menu visibility

  const ETH_TO_USD_RATE = 2000; // Fixed conversion rate: 1 ETH = $2000

  const handleTransfer = () => {
    if (!walletId || !receiverWalletId || !amount) {
      setNotification("Please fill all fields.");
      return;
    }

    if (parseInt(amount) > totalCoins) {
      setNotification("Insufficient ETH.");
      return;
    }

    const newTransaction = {
      id: transactionHistory.length + 1,
      from: walletId,
      to: receiverWalletId,
      amount: parseInt(amount),
      date: new Date().toLocaleString(),
      type: "Transfer",
      status: "Completed",
    };

    setTransactionHistory([...transactionHistory, newTransaction]);
    setTotalCoins(totalCoins - parseInt(amount));
    setNotification("Transfer successful!");
    setWalletId("");
    setReceiverWalletId("");
    setAmount("");
  };

  const handleConversion = () => {
    if (!conversionAmount) {
      setNotification("Please enter an amount.");
      return;
    }

    if (conversionType === "coinToUsd") {
      setConversionResult(`$${(conversionAmount * ETH_TO_USD_RATE).toFixed(2)}`);
    } else {
      setConversionResult(`${(conversionAmount / ETH_TO_USD_RATE).toFixed(6)} ETH`);
    }
    setConversionAmount("");
  };

  const handleDeposit = () => {
    if (!depositAmount || !depositBankAccount) {
      setNotification("Please fill all fields.");
      return;
    }

    const usdAmount = parseFloat(depositAmount);
    if (isNaN(usdAmount) || usdAmount <= 0) {
      setNotification("Invalid deposit amount.");
      return;
    }

    // Convert USD to ETH
    const ethAmount = usdAmount / ETH_TO_USD_RATE;
    setTotalCoins(totalCoins + ethAmount);

    // Add deposit transaction to history
    const newTransaction = {
      id: transactionHistory.length + 1,
      from: "Bank Account",
      to: "ETH Wallet",
      amount: ethAmount.toFixed(6),
      date: new Date().toLocaleString(),
      type: "Deposit",
      status: "Completed",
    };
    setTransactionHistory([...transactionHistory, newTransaction]);

    setNotification(`Successful Deposit: ${ethAmount.toFixed(6)} ETH added.`);
    setDepositAmount("");
    setDepositBankAccount("");
  };

  const handleWithdraw = () => {
    if (!withdrawAmount || !withdrawBankAccount) {
      setNotification("Please fill all fields.");
      return;
    }

    const ethAmount = parseFloat(withdrawAmount);
    if (isNaN(ethAmount) || ethAmount <= 0 || ethAmount > totalCoins) {
      setNotification("Invalid or insufficient ETH.");
      return;
    }

    // Convert ETH to USD
    const usdAmount = ethAmount * ETH_TO_USD_RATE;
    setTotalCoins(totalCoins - ethAmount);

    // Add withdrawal transaction to history
    const newTransaction = {
      id: transactionHistory.length + 1,
      from: "ETH Wallet",
      to: "Bank Account",
      amount: ethAmount.toFixed(6),
      date: new Date().toLocaleString(),
      type: "Withdrawal",
      status: "Completed",
    };
    setTransactionHistory([...transactionHistory, newTransaction]);

    setNotification(`Successful Withdrawal: $${usdAmount.toFixed(2)} sent to your bank account.`);
    setWithdrawAmount("");
    setWithdrawBankAccount("");
  };

  const toggle2FA = () => {
    setIs2FAEnabled(!is2FAEnabled);
    setNotification(`2FA ${is2FAEnabled ? "Disabled" : "Enabled"}`);
  };

  return (
    <div className="dashboard">
      <h2 className="heading">Dashboard</h2>
      {accountStatus === "blocked" && (
        <div className="blockedBanner">
          Your account is blocked. Contact support.
        </div>
      )}
      {notification && (
        <Notification
          message={notification}
          onClose={() => setNotification("")}
        />
      )}
      <div className="tabs">
        <button
          onClick={() => setActiveTab("transfer")}
          className={activeTab === "transfer" ? "activeTab" : "tab"}
        >
          Transfer ETH
        </button>
        <button
          onClick={() => setActiveTab("total")}
          className={activeTab === "total" ? "activeTab" : "tab"}
        >
          Total ETH
        </button>
        <button
          onClick={() => setActiveTab("history")}
          className={activeTab === "history" ? "activeTab" : "tab"}
        >
          Transaction History
        </button>
        <button
          onClick={() => setActiveTab("conversion")}
          className={activeTab === "conversion" ? "activeTab" : "tab"}
        >
          ETH Conversion
        </button>
        <button
          onClick={() => setActiveTab("deposit")}
          className={activeTab === "deposit" ? "activeTab" : "tab"}
        >
          Deposit
        </button>
        <button
          onClick={() => setActiveTab("withdraw")}
          className={activeTab === "withdraw" ? "activeTab" : "tab"}
        >
          Withdraw
        </button>
      </div>

      {activeTab === "transfer" && (
        <div className="transferTab">
          <h3>Transfer ETH</h3>
          <input
            type="text"
            placeholder="Your Wallet ID"
            value={walletId}
            onChange={(e) => setWalletId(e.target.value)}
            className="input"
          />
          <input
            type="text"
            placeholder="Receiver Wallet ID"
            value={receiverWalletId}
            onChange={(e) => setReceiverWalletId(e.target.value)}
            className="input"
          />
          <input
            type="number"
            placeholder="Amount"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="input"
          />
          <button
            onClick={handleTransfer}
            className="button"
            disabled={!walletId || !receiverWalletId || !amount}
          >
            Transfer
          </button>
        </div>
      )}

      {activeTab === "total" && (
        <div className="totalTab">
          <h3>Total ETH</h3>
          <p>You have {totalCoins.toFixed(6)} ETH.</p>
        </div>
      )}

      {activeTab === "history" && (
        <div className="historyTab">
          <h3>Transaction History</h3>
          {transactionHistory.length === 0 ? (
            <p>No transactions yet.</p>
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Date/Time</th>
                  <th>Type</th>
                  <th>Amount</th>
                  <th>From</th>
                  <th>To</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {transactionHistory.map((transaction) => (
                  <tr key={transaction.id}>
                    <td>{transaction.date}</td>
                    <td>{transaction.type}</td>
                    <td>{transaction.amount}</td>
                    <td>{transaction.from}</td>
                    <td>{transaction.to}</td>
                    <td>{transaction.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === "conversion" && (
        <div className="conversionTab">
          <h3>ETH Conversion</h3>
          <p>Total ETH: {totalCoins.toFixed(6)}</p>
          <select
            value={conversionType}
            onChange={(e) => setConversionType(e.target.value)}
            className="input"
          >
            <option value="coinToUsd">ETH to USD</option>
            <option value="usdToCoin">USD to ETH</option>
          </select>
          <input
            type="number"
            placeholder="Amount"
            value={conversionAmount}
            onChange={(e) => setConversionAmount(e.target.value)}
            className="input"
          />
          <button
            onClick={handleConversion}
            className="button"
            disabled={!conversionAmount}
          >
            Convert
          </button>
          {conversionResult && <p>Result: {conversionResult}</p>}
        </div>
      )}

      {activeTab === "deposit" && (
        <div className="depositTab">
          <h3>Deposit</h3>
          <p>Total ETH: {totalCoins.toFixed(6)}</p>
          <input
            type="text"
            placeholder="Bank Account Number"
            value={depositBankAccount}
            onChange={(e) => setDepositBankAccount(e.target.value)}
            className="input"
          />
          <input
            type="number"
            placeholder="Amount in USD"
            value={depositAmount}
            onChange={(e) => setDepositAmount(e.target.value)}
            className="input"
          />
          <button
            onClick={handleDeposit}
            className="button"
            disabled={!depositAmount || !depositBankAccount}
          >
            Deposit
          </button>
        </div>
      )}

      {activeTab === "withdraw" && (
        <div className="withdrawTab">
          <h3>Withdraw</h3>
          <p>Total ETH: {totalCoins.toFixed(6)}</p>
          <input
            type="text"
            placeholder="Bank Account Number"
            value={withdrawBankAccount}
            onChange={(e) => setWithdrawBankAccount(e.target.value)}
            className="input"
          />
          <input
            type="number"
            placeholder="Amount in ETH"
            value={withdrawAmount}
            onChange={(e) => setWithdrawAmount(e.target.value)}
            className="input"
          />
          <button
            onClick={handleWithdraw}
            className="button"
            disabled={!withdrawAmount || !withdrawBankAccount}
          >
            Withdraw
          </button>
        </div>
      )}

      <div className="kycStatus">
        <h3>KYC Status</h3>
        <p>{kycStatus}</p>
      </div>

      {/* Settings Menu */}
      <div className="settingsMenu">
        <button
          className="settingsButton"
          onClick={() => setShowSettings(!showSettings)}
        >
          ⚙️
        </button>
        {showSettings && (
          <div className="settingsContent">
            <h3>Settings</h3>
            <div className="settingItem">
              <label>Enable 2FA</label>
              <div
                className={`toggleSwitch ${is2FAEnabled ? "active" : ""}`}
                onClick={toggle2FA}
              >
                <div className="toggleSlider"></div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
// App Component
const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isAdminLoggedIn, setIsAdminLoggedIn] = useState(false);
  const [isKYCSubmitted, setIsKYCSubmitted] = useState(false);
  const [user, setUser] = useState(null);
  const [kycRequests, setKycRequests] = useState([]);
  const [kycStatus, setKycStatus] = useState("Pending");
  const [accountStatus, setAccountStatus] = useState("active");

  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleAdminLogin = () => {
    setIsAdminLoggedIn(true);
  };

  const handleSignup = (userData) => {
    console.log("User signed up:", userData);
    setUser(userData);
    setIsLoggedIn(true); // Set isLoggedIn to true after successful signup
  };

  const handleKYCSubmit = (kycData) => {
    setKycRequests([...kycRequests, { ...kycData, status: "Pending" }]);
    setIsKYCSubmitted(true);
  };

  const handleApprove = (index) => {
    const updatedRequests = [...kycRequests];
    updatedRequests[index].status = "Approved";
    setKycRequests(updatedRequests);
    setKycStatus("Approved");
  };

  const handleReject = (index) => {
    const updatedRequests = [...kycRequests];
    updatedRequests[index].status = "Rejected";
    setKycRequests(updatedRequests);
    setKycStatus("Rejected");
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route
            path="/login"
            element={
              isLoggedIn ? (
                <Navigate to="/kyc" />
              ) : (
                <LoginPage onLogin={handleLogin} />
              )
            }
          />
          <Route
            path="/admin-login"
            element={
              isAdminLoggedIn ? (
                <Navigate to="/admin" />
              ) : (
                <AdminLogin onAdminLogin={handleAdminLogin} />
              )
            }
          />
          <Route
            path="/forgot-password"
            element={<ForgotPasswordPage />}
          />
          <Route
            path="/signup"
            element={
              isLoggedIn ? (
                <Navigate to="/kyc" />
              ) : (
                <SignupPage onSignup={handleSignup} />
              )
            }
          />
          <Route
            path="/kyc"
            element={
              isKYCSubmitted ? (
                <Navigate to="/dashboard" />
              ) : isLoggedIn ? (
                <KYCForm onKYCSubmit={handleKYCSubmit} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/dashboard"
            element={
              isKYCSubmitted ? (
                <Dashboard user={user} kycStatus={kycStatus} accountStatus={accountStatus} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/admin"
            element={
              isAdminLoggedIn ? (
                <AdminPanel
                  kycRequests={kycRequests}
                  onApprove={handleApprove}
                  onReject={handleReject}
                />
              ) : (
                <Navigate to="/admin-login" />
              )
            }
          />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
